        {
          "name": "shock3_impulse_I3",
          "value": 4.88,
          "uncertainty": "Reported as I_3 = 4.88 Pa*s, no uncertainty given.",
          "unit": "Pa*s",
          "role": "Impulse of third shock in suppression case",
          "anchors": [
            {
              "line_start": 210,
              "line_end": 210,
              "support": "Third shock at t3 approx 1.75 us with impulse I3 = 4.88 Pa*s."
            }
          ]
        },
        {
          "name": "total_impulse_suppression",
          "value": 25.88,
          "uncertainty": "Computed as sum of I1+I2+I3 = 1.6+19.4+4.88 = 25.88 Pa*s; not explicitly stated but implied by the model.",
